inline constexpr std::array<char, 4> MARK = {'F', 'Z', 'R', 'P'};
inline constexpr std::array<char, 4> FRAMES_MARK = {'F', 'Z', 'R', 'F'};
inline constexpr std::array<char, 4> LINEUP_MARK = {'F', 'Z', 'R', 'L'};
inline constexpr std::array<char, 4> RESULTS_MARK = {'F', 'Z', 'R', 'S'};

// version 2: a race of the disc's own car data and none of the features below
inline constexpr std::uint16_t VERSION_PLAIN = 2;
// version 3: the race ran on a stat pack (the header's match.setup.stats)
inline constexpr std::uint16_t VERSION_STATS = 3;
// version 4: a seat raced a custom machine (a seat's match.setup.seats[].custom)
inline constexpr std::uint16_t VERSION_CUSTOM = 4;
// version 5: the race's mines came back (match.setup.rules.mineRegenMs gives a step or more)
inline constexpr std::uint16_t VERSION_MINES = 5;
// version 6: a seat raced a pack of its own (match.setup.packs, a seat's pack)
inline constexpr std::uint16_t VERSION_SEATS = 6;
// version 7: 0.4.0's set-up: the race started on the coordinator's grid (match.setup.grid) or raced with no rubber band
// (the header's rubberBand false: every race and practice from 0.4.0)
inline constexpr std::uint16_t VERSION_GRID = 7;
inline constexpr std::uint16_t VERSION_WRITTEN = 7;  // the only one written

inline constexpr std::size_t HEAD_SIZE = 10;  // the mark, the version, the header's length
inline constexpr std::size_t FRAMES_SIZE = 12;  // the mark, the mask, the seat
inline constexpr std::size_t LINEUP_SIZE = 124;  // the block, after its mark and length
inline constexpr std::size_t LINEUP_LEAST = 122;  // the shortest block a playback reads
inline constexpr std::size_t LINEUP_PART = 8 + LINEUP_SIZE;
inline constexpr std::size_t RECORD_SIZE = 6;  // a seat's control record (relay.toml)
inline constexpr std::size_t CHECKSUM_SIZE = 4;
inline constexpr std::size_t RESULTS_TAIL = 8;  // after the results' JSON: its length, the mark
inline constexpr std::size_t MAX_BYTES = 268435456;
inline constexpr std::size_t MAX_STEPS = 1296000;
inline constexpr std::size_t MAX_JSON = 1048576;
inline constexpr std::uint32_t MAX_SEATS = 30;

// Whether a reader of the game plays a file of this version.
constexpr bool Played(std::uint32_t version)
{
  return version == 2 || version == 3 || version == 4 || version == 5 || version == 6 || version == 7;
}

// What a race holds that a version says (replay.toml's features).
struct Features
{
  bool stats = false;  // Stats
  bool custom = false;  // Custom
  bool mines = false;  // Mines
  bool seat_packs = false;  // Seats
  bool grid = false;  // Grid
};

// The version a race of these features is written as, and the only one its file may be: the highest whose
// feature it holds, else the first.
constexpr std::uint16_t VersionOf(const Features& f)
{
  if (f.grid)
    return VERSION_GRID;
  if (f.seat_packs)
    return VERSION_SEATS;
  if (f.mines)
    return VERSION_MINES;
  if (f.custom)
    return VERSION_CUSTOM;
  if (f.stats)
    return VERSION_STATS;
  return VERSION_PLAIN;
}

